changeSet.sql:

if not exists (select 1 from FusionType where ID = 116)
begin
	SET IDENTITY_INSERT dbo.FusionType ON;
	insert into [FusionType] (ID, Name, Description, UpdatedOn, UpdatedBy) 
	values (116, 'Technology Asset', 'Technology Asset', getutcdate(), 0);
	SET IDENTITY_INSERT dbo.FusionType OFF;
end


if not exists (select 1 from Fusion where ID = 0)
begin
	SET IDENTITY_INSERT dbo.Fusion ON;
	insert into [Fusion] (ID, FusionTypeID, Name, Description, [Enabled], [Manual], LockPromotedItems, IntervalType, [Interval], ForceRefresh, UpdatedOn, UpdatedBy) 
	values (0, 116, 'Technology Asset Configuration', '', 0, 0, 0, 3, 15, 0, getutcdate(), 0);
	SET IDENTITY_INSERT dbo.Fusion OFF;
end


if not exists (select 1 from FusionAttributeType where ID = 1820)
begin
	SET IDENTITY_INSERT dbo.FusionAttributeType ON;
	insert into [FusionAttributeType] (ID, FusionTypeID, Name, Assignable, UpdatedOn, UpdatedBy, ScanEnabled) 
	values (1820, 116, 'Asset', 1, getutcdate(), 0, 1);
	SET IDENTITY_INSERT dbo.FusionAttributeType OFF;
end
